gin:15px 0;padding:8px 15px;color:#a9c4cd;background:rgba(67,194,229,.05);border-radius:0 10px 10px 0}.editor h2{font-size:24px}.media-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:14px 0}.media-gallery img{width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:10px;display:block}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.save{border:0;border-radius:11px;padding:12px 16px;background:#29aaca;color:#fff;font-weight:700}.errors,.notice{padding:11px;border-radius:10px;margin-bottom:14px;font-size:10px}.errors{background:rgba(210,65,65,.12);color:#ffb0b0}.notice{background:rgba(67,194,137,.1);color:#a8e5ca}@media(max-width:650px){.hero{align-items:flex-start;gap:12px;flex-direction:column}.grid{grid-template-columns:1fr}.full{grid-column:auto}.editor{min-height:360px}.editor-toolbar{position:sticky;top:0;z-index:2}.actions{justify-content:stretch}.actions>*{flex:1;justify-content:center;text-align:center}.save{width:100%}.media-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>@endpush
